import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = '/home/runner/.local/share/omgithub-playwright';
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(`${process.env.RUNTIME_DIR}/scripts/display`, 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
try {
  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  desktop.on('pageerror', e => errors.push(e.message));
  await desktop.goto('http://127.0.0.1:3002', { waitUntil: 'load' });
  await desktop.locator('#play-button').click();
  await desktop.waitForTimeout(500);
  await desktop.keyboard.press('Space');
  await desktop.keyboard.press('f');
  if (!await desktop.locator('.fly-btn').evaluate(el => el.classList.contains('active'))) throw new Error('F did not toggle flight');
  await desktop.keyboard.press('f');
  await desktop.keyboard.press('t');
  if (!await desktop.locator('.lock-btn').evaluate(el => el.classList.contains('active'))) throw new Error('T did not toggle aim lock');
  await desktop.keyboard.press('t');
  await desktop.keyboard.down('r');
  await desktop.waitForTimeout(300);
  await desktop.keyboard.up('r');
  await desktop.keyboard.down('c');
  await desktop.waitForTimeout(300);
  await desktop.keyboard.up('c');
  await desktop.keyboard.press('j');
  await desktop.waitForTimeout(900);
  await desktop.screenshot({ path: `${out}/fight.jpg`, type: 'jpeg', quality: 78 });
  console.log('Desktop: controls exercised; saved fight.jpg (1280x800)');
  await desktop.close();

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  mobile.on('pageerror', e => errors.push(e.message));
  await mobile.goto('http://127.0.0.1:3002', { waitUntil: 'load' });
  await mobile.locator('#play-button').click();
  await mobile.waitForTimeout(700);
  await mobile.screenshot({ path: `${out}/mobile.jpg`, type: 'jpeg', quality: 78 });
  const controlCount = await mobile.locator('.action-btn').count();
  if (controlCount < 5) throw new Error(`Expected touch controls, found ${controlCount}`);
  console.log(`Mobile: ${controlCount} touch controls present; saved mobile.jpg (390x844)`);
  await mobile.close();
  if (errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
} finally {
  await browser.close();
}

